    private static DbDataReader AsReader(WidgetDto? row)
    {
        var table = new DataTable();
        table.Columns.Add("Id", typeof(int));
        table.Columns.Add("Name", typeof(string));
        table.Columns.Add("Quantity", typeof(int));
        if (row != null)
