    // Upsert hits Query* then Execute*; Moq.Dapper's last SetupDapperAsync wins, so we
    // reuse the query-backed command and bolt ExecuteNonQueryAsync onto it.
    private static List<string> AllowLookupThenWrite(Mock<DbConnection> db, Queue<WidgetDto?> lookups)
    {
        var statements = new List<string>();

        db.SetupDapperAsync(c =>
                c.QueryFirstOrDefaultAsync<WidgetDto>(It.IsAny<string>(), It.IsAny<object>(), null, null, null))
            .ReturnsAsync(lookups.Count > 0 ? lookups.Peek()! : null!);

        var cmd = Mock.Get(db.Object.CreateCommand());
        cmd.SetupSet(c => c.CommandText = It.IsAny<string>()).Callback<string>(statements.Add);

        cmd.Protected()
            .Setup<Task<DbDataReader>>("ExecuteDbDataReaderAsync",
                ItExpr.IsAny<CommandBehavior>(), ItExpr.IsAny<CancellationToken>())
            .ReturnsAsync(() => AsReader(lookups.Count > 0 ? lookups.Dequeue() : null));

        cmd.Setup(c => c.ExecuteNonQueryAsync(It.IsAny<CancellationToken>())).ReturnsAsync(1);

        return statements;
    }

    [Fact]
    public async Task DeleteByKeyAsync_IssuesDeleteForKey()
    {
        var db = MockDb();
        db.SetupDapperAsync(c =>
                c.ExecuteAsync(It.IsAny<string>(), It.IsAny<object>(), null, null, null))
            .ReturnsAsync(1);

        // Execute path is registered on IDbConnection.CreateCommand, not CreateDbCommand.
        var command = ((IDbConnection) db.Object).CreateCommand();

        await StorageFor(db.Object).DeleteByKeyAsync(9);

        Assert.Equal("DELETE FROM `widgets` WHERE `Id`=@key\n", command.CommandText);
    }

    [Fact]
