    [Fact]
    public async Task GetByKeyAsync_IssuesSelectForKey()
    {
        var expected = new WidgetDto {Id = 7, Name = "beta", Quantity = 1};

        var db = MockDb();
        db.SetupDapperAsync(c =>
                c.QueryFirstOrDefaultAsync<WidgetDto>(It.IsAny<string>(), It.IsAny<object>(), null, null, null))
            .ReturnsAsync(expected);

        // Same DbCommand instance Moq.Dapper will hand to Dapper.
        var command = db.Object.CreateCommand();

        await StorageFor(db.Object).GetByKeyAsync(7);

        Assert.Equal("SELECT * FROM `widgets` WHERE `Id` = @entryId", command.CommandText);
    }

    [Fact]
    public async Task GetByKeyAsync_ReturnsMappedDto()
    {
        var expected = new WidgetDto {Id = 42, Name = "alpha", Quantity = 3};

        var db = MockDb();
        db.SetupDapperAsync(c =>
                c.QueryFirstOrDefaultAsync<WidgetDto>(It.IsAny<string>(), It.IsAny<object>(), null, null, null))
            .ReturnsAsync(expected);

        var result = await StorageFor(db.Object).GetByKeyAsync(42);

        Assert.NotNull(result);
        Assert.Equal(expected.Id, result.Id);
        Assert.Equal(expected.Name, result.Name);
        Assert.Equal(expected.Quantity, result.Quantity);
