    [Fact]
    public async Task UpsertAsync_InsertsWhenMissing()
    {
        var dto = new WidgetDto {Id = 1, Name = "gamma", Quantity = 5};

        var db = MockDb();
        var capturedSql = AllowLookupThenWrite(db, new Queue<WidgetDto?>([null]));

        var result = await StorageFor(db.Object).UpsertAsync(dto);

        Assert.Same(dto, result);
        Assert.NotNull(capturedSql);
        var insertSql = Assert.Single(capturedSql,
            sql => sql.StartsWith("INSERT INTO `widgets` (", StringComparison.Ordinal));
        Assert.Contains("`Id`", insertSql);
        Assert.Contains("`widget_name`", insertSql);
        Assert.Contains("`Quantity`", insertSql);
        Assert.Contains("@Id", insertSql);
        Assert.Contains("@widget_name", insertSql);
        Assert.Contains("@Quantity", insertSql);
    }

    [Fact]
    public async Task UpsertAsync_UpdatesWhenExistingAndChanged()
    {
        var existing = new WidgetDto {Id = 2, Name = "old", Quantity = 1};
        var updated = new WidgetDto {Id = 2, Name = "new", Quantity = 1};

        var db = MockDb();
        // Second dequeue is the post-update reload inside UpdateAsync.
        var capturedSql = AllowLookupThenWrite(db, new Queue<WidgetDto?>([existing, updated]));

        var result = await StorageFor(db.Object).UpsertAsync(updated);

        Assert.Equal("new", result.Name);
        Assert.NotNull(capturedSql);
        Assert.Contains("UPDATE `widgets` SET `Name`=@Name\n WHERE `Id`=@key\n", capturedSql);
    }

    [Table("widgets")]
    public sealed class WidgetDto
